import ee, math, sys
ee.Initialize(project='earthsense-436113')

# 1. Geometry & Time Definitions
geom = ee.Geometry.Rectangle([-74.05, 40.56, -73.83, 40.74])  # Brooklyn area bbox
years = [2018, 2019, 2021]
band = 'tropospheric_NO2_column_number_density'
datasets = [
    ('COPERNICUS/S5P/OFFL/L3_NO2', 'OFFL'),
    ('COPERNICUS/S5P/NRTI/L3_NO2', 'NRTI'),
]

def get_year_stats(year):
    start = f"{year}-10-01"
    end   = f"{year}-10-24"  # end exclusive to cover Oct 1–23
    chosen_col = None
    src = None
    imgs = 0
    # Try datasets in order
    for ds_id, src_name in datasets:
        col = (ee.ImageCollection(ds_id)
               .select([band, 'qa_value'])
               .filterDate(start, end)
               .filterBounds(geom))
        imgs = col.size().getInfo()
        if imgs and imgs > 0:
            chosen_col = col
            src = src_name
            break
    if chosen_col is None or imgs == 0:
        print(f"{year}: imgs=0")
        return {'status':'C1'}
    # Masking
    def mask_no2(img):
        return img.updateMask(img.select('qa_value').gt(0.75))
    colm = chosen_col.map(mask_no2).select(band)
    mean_img = colm.mean()
    # Pixel counts
    total_count = ee.Image(1).rename('const').reduceRegion(
        reducer=ee.Reducer.count(), geometry=geom, scale=1000, maxPixels=1e9
    ).get('const').getInfo()
    valid_count = mean_img.reduceRegion(
        reducer=ee.Reducer.count(), geometry=geom, scale=1000, maxPixels=1e9
    ).get(band).getInfo()
    if valid_count is None:
        valid_count = 0
    if total_count is None or total_count == 0:
        print(f"{year} {src}: imgs={imgs}, valid=0/0 (0.0%), mean=None")
        return {'status':'C2'}
    if valid_count == 0:
        print(f"{year} {src}: imgs={imgs}, valid=0/{int(total_count)} (0.0%), mean=None")
        return {'status':'C2'}
    # Mean value
    mean_val = mean_img.reduceRegion(
        reducer=ee.Reducer.mean(), geometry=geom, scale=1000, maxPixels=1e9
    ).get(band).getInfo()
    if mean_val is None or (isinstance(mean_val, float) and (math.isnan(mean_val) or math.isinf(mean_val))):
        print(f"{year} {src}: imgs={imgs}, valid={int(valid_count)}/{int(total_count)} ({100.0*valid_count/total_count:.1f}%), mean=None")
        return {'status':'C3'}
    print(f"{year} {src}: imgs={imgs}, valid={int(valid_count)}/{int(total_count)} ({100.0*valid_count/total_count:.1f}%), mean={mean_val:.6e}")
    return {'status':'OK', 'mean': mean_val}

try:
    results = {}
    statuses = []
    for y in years:
        res = get_year_stats(y)
        results[y] = res
        statuses.append(res['status'])
    # Failure precedence
    if 'C1' in statuses:
        print("C1")
        sys.exit(0)
    if 'C2' in statuses:
        print("C2")
        sys.exit(0)
    if 'C3' in statuses:
        print("C3")
        sys.exit(0)
    # 2021 lower than both 2019 and 2018?
    v2021 = results[2021]['mean']
    v2019 = results[2019]['mean']
    v2018 = results[2018]['mean']
    if v2021 is None or v2019 is None or v2018 is None:
        print("C3")
    elif (v2021 < v2019) and (v2021 < v2018):
        print("A")
    else:
        print("B")
except Exception as e:
    # Minimal error indicator per requirements
    print("D")

