import ee, math
ee.Initialize(project='earthsense-436113')

# 1. Geometry & Time Definitions
geom = ee.Geometry.Rectangle([-74.05, 40.56, -73.83, 40.74])  # Brooklyn bbox
years = [2018, 2019, 2021]
band = 'tropospheric_NO2_column_number_density'
datasets = [
    ('COPERNICUS/S5P/OFFL/L3_NO2', 'OFFL'),
    ('COPERNICUS/S5P/NRTI/L3_NO2', 'NRTI'),
]
qa_thresholds = [0.75, 0.5, 0.3]
scale = 3000

def year_stats(year):
    start = f"{year}-10-01"
    end   = f"{year}-10-24"  # end exclusive (covers Oct 1–23)
    chosen_col = None
    src = None
    # Try datasets in order
    for ds_id, src_name in datasets:
        col = (ee.ImageCollection(ds_id)
               .filterDate(start, end)
               .filterBounds(geom)
               .select([band, 'qa_value']))
        try:
            n = col.size().getInfo()
        except Exception:
            n = None
        if n and n > 0:
            chosen_col = col
            src = src_name
            break
    if chosen_col is None:
        print(f"{year}: imgs=0")
        return {'status':'C1'}

    # Try progressively relaxed QA thresholds to avoid C2
    result = None
    used_qa = None
    for qa in qa_thresholds:
        def mask_no2(img):
            return img.updateMask(img.select('qa_value').gt(qa)).select([band])
        colm = chosen_col.map(mask_no2)

        def per_img_feat(img):
            combo = img.reduceRegion(
                reducer=ee.Reducer.mean().combine(ee.Reducer.count(), sharedInputs=True),
                geometry=geom, scale=scale, maxPixels=1e9, bestEffort=True
            )
            mean = ee.Number(combo.get(f'{band}_mean'))
            cnt  = ee.Number(combo.get(f'{band}_count'))
            weighted = ee.Algorithms.If(cnt.gt(0), mean.multiply(cnt), 0)
            return ee.Feature(None, {'mean': mean, 'count': cnt, 'weighted': weighted})

        fc = colm.map(per_img_feat)
        try:
            imgs = chosen_col.size().getInfo()
            valid_days = fc.filter(ee.Filter.gt('count', 0)).size().getInfo()
            total_valid_px = ee.Number(fc.aggregate_sum('count')).getInfo()
            weighted_sum = ee.Number(fc.aggregate_sum('weighted')).getInfo()
        except Exception:
            print("D")
            return {'status':'D'}

        if total_valid_px and total_valid_px > 0:
            mean_val = weighted_sum / total_valid_px if total_valid_px > 0 else None
            result = {'src': src, 'imgs': imgs, 'valid_days': valid_days,
                      'valid_px': int(total_valid_px), 'mean': mean_val, 'qa': qa}
            used_qa = qa
            break

    if result is None:
        print(f"{year} {src}: imgs={imgs}, validDays=0, px=0, mean=None")
        return {'status':'C2'}

    mean_val = result['mean']
    invalid = (mean_val is None) or (isinstance(mean_val, float) and (math.isnan(mean_val) or math.isinf(mean_val))) \
              or (mean_val < 0) or (mean_val > 0.005)
    if invalid:
        print(f"{year} {result['src']} qa={used_qa:.2f}: imgs={result['imgs']}, validDays={result['valid_days']}, px={result['valid_px']}, mean=None")
        return {'status':'C3'}

    print(f"{year} {result['src']} qa={used_qa:.2f}: imgs={result['imgs']}, validDays={result['valid_days']}, px={result['valid_px']}, mean={mean_val:.6e}")
    return {'status':'OK', 'mean': float(mean_val)}

# Run, guard failures, and final decision
try:
    results = {}
    statuses = []
    for y in years:
        res = year_stats(y)
        results[y] = res
        statuses.append(res['status'])

    if 'D' in statuses:
        print("D")
    elif 'C1' in statuses:
        print("C1")
    elif 'C2' in statuses:
        print("C2")
    elif 'C3' in statuses:
        print("C3")
    else:
        v2021 = results[2021]['mean']
        v2019 = results[2019]['mean']
        v2018 = results[2018]['mean']
        if (v2021 is None) or (v2019 is None) or (v2018 is None):
            print("C3")
        elif (v2021 < v2019) and (v2021 < v2018):
            print("A")
        else:
            print("B")
except Exception:
    print("D")
